  function normalizeBackendUrl(value) {
    const candidate = (value || "").trim() || DEFAULT_API_BASE_URL;
    let parsed;
    try {
      parsed = new URL(candidate);
    } catch (_err) {
      throw new Error("Enter a valid backend URL.");
    }

    const isLoopback = parsed.protocol === "http:" &&
      (parsed.hostname === "127.0.0.1" || parsed.hostname === "localhost") &&
      parsed.port === "5000";
    if (parsed.protocol !== "https:" && !isLoopback) {
      throw new Error("Remote backends must use HTTPS. HTTP is allowed only for localhost.");
    }
    if (parsed.username || parsed.password || parsed.search || parsed.hash || parsed.pathname !== "/") {
      throw new Error("Enter only the backend origin, without credentials, a path, or query parameters.");
    }
    return parsed.origin;
  }

  if (backendUrlInput) {
    if (typeof chrome !== "undefined" && chrome.storage && chrome.storage.local) {
      chrome.storage.local.get(["backendUrl"], (res) => {
        if (res && res.backendUrl) {
          try {
            const savedUrl = normalizeBackendUrl(res.backendUrl);
            if (savedUrl.startsWith("https://") && chrome.permissions) {
              chrome.permissions.contains({ origins: [`${savedUrl}/*`] }, (hasPermission) => {
                if (hasPermission) {
                  apiBaseUrl = savedUrl;
                  backendUrlInput.value = savedUrl;
                } else {
                  backendUrlInput.value = DEFAULT_API_BASE_URL;
                  chrome.storage.local.remove("backendUrl");
                  showError("Backend permission needed", "Choose the remote backend URL again to grant access before sending a screenshot.");
                }
              });
              return;
            }
            apiBaseUrl = savedUrl;
            backendUrlInput.value = savedUrl;
          } catch (_err) {
            backendUrlInput.value = DEFAULT_API_BASE_URL;
          }
        }
      });
      backendUrlInput.addEventListener("change", async () => {
        try {
          const val = normalizeBackendUrl(backendUrlInput.value);
          if (val.startsWith("https://") && chrome.permissions) {
            const granted = await chrome.permissions.request({ origins: [`${val}/*`] });
            if (!granted) {
              backendUrlInput.value = apiBaseUrl;
              showError("Backend access not granted", "The screenshot was not sent. Grant access to this backend before using its OCR service.");
              return;
            }
          }
          if (apiBaseUrl.startsWith("https://") && apiBaseUrl !== val && chrome.permissions) {
            await chrome.permissions.remove({ origins: [`${apiBaseUrl}/*`] });
          }
          apiBaseUrl = val;
          backendUrlInput.value = val;
          chrome.storage.local.set({ backendUrl: val });
          hideError();
        } catch (err) {
          backendUrlInput.value = apiBaseUrl;
          showError("Invalid backend URL", err.message);
        }
      });
    } else {
      backendUrlInput.addEventListener("change", () => {
        try {
          apiBaseUrl = normalizeBackendUrl(backendUrlInput.value);
          backendUrlInput.value = apiBaseUrl;
        } catch (err) {
          backendUrlInput.value = apiBaseUrl;
          showError("Invalid backend URL", err.message);
        }
      });
    }
  }

